package com.stackgen.metadataservice.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="llm_generation_logs") public class LlmGenerationLog { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="project_id",nullable=false) private UUID projectId; @Column(columnDefinition="text") private String prompt; @Column(columnDefinition="text") private String response; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); public UUID getId(){return id;} public UUID getProjectId(){return projectId;} public void setProjectId(UUID v){projectId=v;} public String getPrompt(){return prompt;} public void setPrompt(String v){prompt=v;} public String getResponse(){return response;} public void setResponse(String v){response=v;} public Instant getCreatedAt(){return createdAt;} }
